/* Botón activar/silenciar sonido */
(function(){
  var v = document.getElementById("heroVideo"), b = document.getElementById("unmuteBtn"); if(!v||!b) return;
  b.onclick = function(){
    v.muted = !v.muted;
    if(!v.muted){ v.currentTime = 0; v.play().catch(function(){}); b.innerHTML = "🔊 Sonido activado"; }
    else { b.innerHTML = "🔇 Silenciado"; }
  };
})();

/* Carruseles (hero + ingredientes): flechas + puntos */
(function(){
  document.querySelectorAll(".carousel").forEach(function(root){
    var wrap = root.querySelector(".slides");
    var slides = root.querySelectorAll(".slide");
    var dots = root.querySelector(".dots");
    var prev = root.querySelector(".car-prev");
    var next = root.querySelector(".car-next");
    if(!wrap || !slides.length) return;
    var i = 0, n = slides.length;
    if(dots){ for(var k=0;k<n;k++){ (function(k){ var d=document.createElement("button"); d.type="button"; if(k===0)d.className="active"; d.onclick=function(){ go(k); }; dots.appendChild(d); })(k); } }
    function go(x){ i=(x+n)%n; wrap.style.transform="translateX("+(-i*100)+"%)"; if(dots){ var c=dots.children; for(var j=0;j<c.length;j++) c[j].className=(j===i?"active":""); } }
    if(prev) prev.onclick=function(){ go(i-1); };
    if(next) next.onclick=function(){ go(i+1); };
  });
})();

/* Reveal on scroll */
(function(){
  var io = new IntersectionObserver(function(es){
    es.forEach(function(e){ if(e.isIntersecting){ e.target.classList.add("in"); io.unobserve(e.target); } });
  }, {threshold:.12});
  document.querySelectorAll(".reveal").forEach(function(el){ io.observe(el); });
})();

/* Sticky buy bar: aparece al pasar el hero, se esconde en el bloque de precios */
(function(){
  var bar = document.getElementById("buybar"), precios = document.getElementById("precios");
  window.addEventListener("scroll", function(){
    var y = window.scrollY, showFrom = window.innerHeight*0.9;
    var pr = precios.getBoundingClientRect();
    var overPrecios = pr.top < window.innerHeight && pr.bottom > 0;
    if(y > showFrom && !overPrecios){ bar.classList.add("show"); } else { bar.classList.remove("show"); }
  }, {passive:true});
})();

